sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float strength;
layout(color) uniform half4 outlineColor;
half luma(half3 c) { return dot(c, half3(0.2126, 0.7152, 0.0722)); }
half l(float2 p) { return luma(image.eval(p).rgb); }
half4 main(float2 coord) {
    half4 col = image.eval(coord);
    if (col.a < 1e-3) return half4(0);
    float3 rgb = float3(col.rgb / col.a);
    float levels = clamp(24.0 - strength * 0.5, 2.0, 24.0);
    float3 q = clamp(floor(rgb * levels) / levels, 0.0, 1.0);
    half gx = l(coord + float2(1, -1)) + 2 * l(coord + float2(1, 0)) + l(coord + float2(1, 1))
            - l(coord + float2(-1, -1)) - 2 * l(coord + float2(-1, 0)) - l(coord + float2(-1, 1));
    half gy = l(coord + float2(-1, 1)) + 2 * l(coord + float2(0, 1)) + l(coord + float2(1, 1))
            - l(coord + float2(-1, -1)) - 2 * l(coord + float2(0, -1)) - l(coord + float2(1, -1));
    float edge = float(length(half2(gx, gy)));
    float line = step(0.5, edge);
    float3 outRgb = mix(q, float3(outlineColor.rgb), line * float(outlineColor.a));
    return half4(half3(outRgb) * col.a, col.a);
}
